import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"정보 및 업데이트","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/about.md","filePath":"ko-KR/user-guide/settings/about.md","lastUpdated":1787586465000}'),i={name:"ko-KR/user-guide/settings/about.md"};function s(n,t,l,d,c,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="정보-및-업데이트" tabindex="-1">정보 및 업데이트 <a class="header-anchor" href="#정보-및-업데이트" aria-label="Permalink to &quot;정보 및 업데이트&quot;">​</a></h1><p>정보 페이지에서는 Lertaro의 전체 컴포넌트 버전 정보, 사용자 및 시스템 데이터 디렉토리 바로가기, 온라인 업데이트 확인 및 원클릭 무음 업데이트 기능을 제공합니다. 설정 경로는 <strong>설정 → 정보</strong>입니다.</p><h2 id="_1-컴포넌트-버전-및-프로젝트-정보" tabindex="-1">1. 컴포넌트 버전 및 프로젝트 정보 <a class="header-anchor" href="#_1-컴포넌트-버전-및-프로젝트-정보" aria-label="Permalink to &quot;1. 컴포넌트 버전 및 프로젝트 정보&quot;">​</a></h2><p>상단 영역에는 Lertaro 아키텍처를 구성하는 4대 핵심 컴포넌트의 버전이 표시됩니다.</p><ul><li><strong>App 버전</strong>: 전면 WPF 사용자 인터페이스 버전.</li><li><strong>Core 버전</strong>: 검색 및 인덱싱 코어 로직 라이브러리 버전.</li><li><strong>Service 버전</strong>: 백그라운드 Windows 인덱싱 서비스 버전(글자 색상으로 서비스 연결 상태 실시간 반영).</li><li><strong>CLI 버전</strong>: 명령줄 터미널 유틸리티 <code>lff</code> 버전.</li></ul><p>하단에는 공식 웹사이트, GitHub 오픈소스 리포지토리 및 온라인 문서 센터 링크가 제공됩니다.</p><h2 id="_2-데이터-디렉토리-및-5단계-백업-롤링-보관" tabindex="-1">2. 데이터 디렉토리 및 5단계 백업 롤링 보관 <a class="header-anchor" href="#_2-데이터-디렉토리-및-5단계-백업-롤링-보관" aria-label="Permalink to &quot;2. 데이터 디렉토리 및 5단계 백업 롤링 보관&quot;">​</a></h2><p>클릭 시 탐색기로 해당 경로를 바로 열 수 있는 두 개의 링크가 제공됩니다(폴더가 없으면 자동 생성):</p><h3 id="사용자-데이터-디렉토리-user-data-directory" tabindex="-1">사용자 데이터 디렉토리 (User Data Directory) <a class="header-anchor" href="#사용자-데이터-디렉토리-user-data-directory" aria-label="Permalink to &quot;사용자 데이터 디렉토리 (User Data Directory)&quot;">​</a></h3><ul><li><strong>저장 내용</strong>: 사용자 설정 파일(<code>user-settings.json</code>), 검색 및 키워드 기록, 사용자 전용 캐시 및 보안 인증서.</li><li><strong>5단계 백업 롤링 보관</strong>: 설정을 저장할 때마다 기존 설정 파일이 <code>user-settings.json.bak.1</code>로 순환 백업되며 최대 <code>.bak.5</code>까지 유지됩니다. 오류나 시스템 충돌 시에도 최근 5회의 백업에서 안전하게 복원할 수 있습니다.</li></ul><h3 id="머신-데이터-디렉토리-machine-data-directory" tabindex="-1">머신 데이터 디렉토리 (Machine Data Directory) <a class="header-anchor" href="#머신-데이터-디렉토리-machine-data-directory" aria-label="Permalink to &quot;머신 데이터 디렉토리 (Machine Data Directory)&quot;">​</a></h3><ul><li><strong>저장 내용</strong>: 관리자 권한 서비스용 설정(<code>machine-settings.json</code>), 디스크 물리 인덱스 영구 캐시 및 백그라운드 서비스 로그.</li></ul><h3 id="저장-경로-아키텍처" tabindex="-1">저장 경로 아키텍처 <a class="header-anchor" href="#저장-경로-아키텍처" aria-label="Permalink to &quot;저장 경로 아키텍처&quot;">​</a></h3><ul><li><strong>설치형 버전</strong>: 사용자 데이터는 <code>%LocalAppData%\\Lertaro</code>, 머신 데이터는 <code>%ProgramData%\\Lertaro</code>에 보관.</li><li><strong>포터블 버전</strong>: 프로그램 실행 파일 옆의 <code>Data\\Users\\&lt;SID hash&gt;</code> 및 <code>Data\\Machine</code>에 보관되어 완전한 격리형 무설치 환경 지원(<a href="./../getting-started.html#포터블-데이터-격리-구조"><strong>포터블 데이터 격리 안내</strong></a> 참고).</li></ul><h2 id="_3-업데이트-확인-및-원클릭-업데이트" tabindex="-1">3. 업데이트 확인 및 원클릭 업데이트 <a class="header-anchor" href="#_3-업데이트-확인-및-원클릭-업데이트" aria-label="Permalink to &quot;3. 업데이트 확인 및 원클릭 업데이트&quot;">​</a></h2><ul><li><strong>업데이트 확인 버튼</strong>: 온라인 리포지토리에 새 버전을 질의하고 상태를 버튼에 표시(&quot;업데이트 확인 중...&quot; → &quot;최신 버전입니다&quot; 또는 새 버전 안내).</li><li><strong>새 버전 발견 시 업그레이드 방식</strong>: <ul><li><strong>무음 자동 업데이트</strong> —— 백그라운드에서 다운로드 후 즉시 덮어쓰기 업데이트를 수행하고 완료 후 자동 재시작.</li><li><strong>다운로드 페이지로 이동</strong> —— 기본 브라우저로 GitHub Releases 페이지를 열어 수동 다운로드.</li></ul></li><li><strong>권한 안내</strong>: 표준 사용자 계정에서 백그라운드 서비스를 재시작할 수 없는 경우 수동 다운로드 페이지로 안내하는 배너가 표시됩니다.</li></ul>',16)])])}const _=a(i,[["render",s]]);export{g as __pageData,_ as default};
